begin;
set local request.jwt.claim.role='service_role';
do $$
declare u uuid:=(select id from profiles where is_admin order by id limit 1);v uuid;prod uuid;slug text;
 o uuid:=gen_random_uuid();rbo uuid:=gen_random_uuid();full_o uuid:=gen_random_uuid();min_o uuid:=gen_random_uuid();test_o uuid:=gen_random_uuid();r jsonb;b numeric;n numeric;c numeric;
begin
 select id into v from profiles where id<>u limit 1;if v is null then raise exception 'Test requires two existing profiles';end if;
 select id,products.slug into prod,slug from products where products.slug='japanese-anime-asset-pack';
 insert into store_credit_ledger(user_id,currency,amount,kind) values(u,'usd',30,'payout'),(u,'robux',100,'payout');
 select (store_credit_balances(u)->>'usd')::numeric into b;
 insert into orders(id,user_id,status,currency,subtotal_usd,total_usd,payment_provider,referrer_id,ref_product_slug) values(o,u,'pending','usd',10,10,'stripe',v,slug);
 insert into order_items(order_id,product_id,product_slug,title,unit_price_usd,qty,licence) values(o,prod,slug,'Partial credit regression',10,1,'standard');
 r:=apply_store_credit(u,o,'usd',3,0.5);if not(r->>'ok')::boolean or (r->>'due')::numeric<>7 or(r->>'paid')::boolean then raise exception 'Partial USD reservation failed: %',r;end if;
 if(store_credit_balances(u)->>'usd')::numeric<>b-3 then raise exception 'USD reservation not deducted';end if;
 if(select status from orders where id=o)<>'pending' then raise exception 'Part-paid order fulfilled early';end if;
 r:=apply_store_credit(u,o,'usd',3,0.5);if(select count(*) from store_credit_ledger where order_id=o and kind='purchase')<>1 then raise exception 'Duplicate reservation';end if;
 update orders set status='paid' where id=o;
 if(select amount from referral_order_earnings where order_id=o and currency='usd')<>1.4 then raise exception 'Cash referral split failed';end if;
 if(select amount from referral_order_earnings where order_id=o and currency='store_usd')<>0.6 then raise exception 'Credit referral split failed';end if;
 update orders set status='refunded' where id=o;update orders set status='refunded' where id=o;
 if(store_credit_balances(u)->>'usd')::numeric<>b then raise exception 'Mixed refund not restored once';end if;
 if exists(select 1 from referral_order_earnings where order_id=o) then raise exception 'Refund retained commission';end if;
 insert into orders(id,user_id,status,currency,subtotal_usd,total_usd)values(full_o,u,'pending','usd',5,5);
 r:=apply_store_credit(u,full_o,'usd',5);if not(r->>'paid')::boolean or(r->>'due')::numeric<>0 then raise exception 'Full credit checkout failed';end if;
 insert into orders(id,user_id,status,currency,subtotal_usd,total_usd)values(min_o,u,'pending','usd',1,1);
 r:=apply_store_credit(u,min_o,'usd',0.8,0.5);if(r->>'applied')::numeric<>0.5 or(r->>'due')::numeric<>0.5 then raise exception 'Card minimum remainder failed';end if;
 update orders set status='canceled' where id=min_o;
 if(select count(*) from store_credit_ledger where order_id=min_o and kind='refund')<>1 then raise exception 'Cancellation did not restore reservation';end if;
 begin update orders set status='paid' where id=min_o;raise exception 'Late payment reopened canceled order';exception when raise_exception then if sqlerrm='Late payment reopened canceled order' then raise;end if;end;
 insert into orders(id,user_id,status,currency,subtotal_usd,total_usd,total_robux,payment_provider,referrer_id,ref_product_slug) values(rbo,u,'pending','robux',10,10,100,'robux',v,slug);
 insert into order_items(order_id,product_id,product_slug,title,unit_price_usd,unit_price_robux,qty,licence)values(rbo,prod,slug,'Robux partial regression',10,100,1,'standard');
 r:=apply_store_credit(u,rbo,'usd',1);if(r->>'ok')::boolean then raise exception 'Cross currency accepted';end if;
 r:=apply_store_credit(u,rbo,'robux',1.5);if(r->>'ok')::boolean then raise exception 'Fractional Robux accepted';end if;
 r:=apply_store_credit(u,rbo,'robux',40,1);if(r->>'due')::numeric<>60 then raise exception 'Robux remainder wrong';end if;
 update orders set status='paid' where id=rbo;
 if(select amount from referral_order_earnings where order_id=rbo and currency='robux')<>12 or(select amount from referral_order_earnings where order_id=rbo and currency='store_robux')<>8 then raise exception 'Robux referral split failed';end if;
 update orders set status='refunded' where id=rbo;
 insert into orders(id,user_id,status,currency,subtotal_usd,total_usd)values(test_o,u,'pending','usd',2,2);
 r:=apply_store_credit(u,test_o,'usd',1);select(store_credit_balances(u)->>'usd')::numeric into c;
 update orders set stripe_checkout_session_id='cs_test_partial_credit_regression' where id=test_o;
 update orders set status='paid' where id=test_o;
 if(store_credit_balances(u)->>'usd')::numeric<>c+1 then raise exception 'Sandbox checkout consumed real credit';end if;
 r:=apply_store_credit(u,gen_random_uuid(),'usd',1);if(r->>'ok')::boolean then raise exception 'Unknown order accepted';end if;
end $$;
rollback;
select 'PASS: partial USD/Robux, full credit, provider minimum, reservations, refunds, sandbox restoration, mixed referral currencies, terminal states and duplicate prevention; no fixtures retained' as result;